CREATE TABLE `player_tackles_won` (
  `rank_val` int DEFAULT NULL,
  `player` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `team` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Tackles_per_90` double DEFAULT NULL,
  `Tackle_Success_Rate` double DEFAULT NULL,
  `Minutes` int DEFAULT NULL,
  `Matches` int DEFAULT NULL,
  `Country` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `player_slug` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
